'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
function setup(){const c={window:{}};vm.createContext(c);for(const f of ['white-orchard.js','map-data.js','diagrams-data.js','exploration-data.js','progression-data.js','progression-engine.js','search-model.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);const w=c.window,{tasks,hubs}=w.PHOENIX_ROUTE,engine=w.createPhoenixProgress(w.PHOENIX_PROGRESS_DATA,tasks,hubs),state={progress:engine.init(),completed:{}},model=w.PhoenixSearchModel,index=model.buildIndex({tasks,pins:w.PHOENIX_MAP.markers,references:[{id:'ref-economy',title:'Economy',href:'#economy',keywords:'crowns merchants'},{id:'bad',title:'Bad link',href:'https://example.com'}]});return {model,index,tasks,state,engine,find(q,filters){return model.search(index,q,filters,{tasks,state,engine});}};}
test('index has unique identities and safe shared routes, with individual quest steps',()=>{const x=setup();assert.equal(new Set(x.index.map(r=>r.id)).size,x.index.length);assert.ok(x.index.every(r=>r.href.startsWith('#')));assert.equal(x.index.find(r=>r.id==='q-missing').href,'#whiteorchard-tree/hub-missing/q-missing');assert.equal(x.index.find(r=>r.id==='q-missing:step:3').href,'#quest-q-missing/3');assert.ok(!x.index.some(r=>r.id==='bad'));});
test('title matches rank above body matches and all query words must match',()=>{const x=setup(),rows=x.find('Missing in Action');assert.equal(rows[0].id,'q-missing');assert.ok(x.find('Hussar').some(r=>r.id==='q-missing:step:3'));assert.equal(x.find('Hussar nonexistentword').length,0);});
test('normalization handles case, apostrophes, punctuation and accents',()=>{const x=setup();assert.equal(x.model.normalize("  YÉNNEFER’S Crystal-skull "),'yennefers crystal skull');assert.ok(x.find("YENNEFER'S crystal skull").some(r=>r.id==='poi-4'));});
test('spoiler-only branch consequences are excluded from the index',()=>{const x=setup();assert.ok(!x.index.find(r=>r.id==='q-missing:step:3').searchKey.includes('rhosyn'));});
test('blank input has no fabricated results and malicious text is treated literally',()=>{const x=setup();assert.equal(x.find(' ').length,0);assert.equal(x.find('<img src=x onerror=alert(1)>').length,0);});
test('region and content filters combine without losing matching entries',()=>{const x=setup();assert.ok(x.find('Viper',{type:'diagram',region:'White Orchard'}).every(r=>r.type==='diagram'&&r.region==='White Orchard'));assert.equal(x.find('Viper',{region:'Guide-wide'}).length,0);assert.equal(x.find('Economy',{type:'reference',region:'Guide-wide'})[0].id,'ref-economy');});
test('completion labels and filters are derived live from shared progress',()=>{const x=setup();assert.equal(x.find('Viper steel',{completion:'completed'}).length,0);x.state.completed['diagram-viper-steel']=true;const rows=x.find('Viper steel',{type:'diagram',completion:'completed'});assert.equal(rows[0].status.label,'Recorded acquired');assert.equal(x.find('Viper steel',{type:'diagram',completion:'open'}).length,0);});
test('quest-step results label quest status without claiming the step is complete',()=>{const x=setup();x.state.progress.legacy['q-missing']=true;const row=x.find('Follow Hussar',{completion:'completed'}).find(r=>r.id==='q-missing:step:3');assert.equal(row.status.label,'Quest: Recorded complete');x.state.progress.failed['q-firestarter']=true;assert.ok(x.find('Twisted Firestarter',{completion:'failed'}).every(r=>r.status.key==='failed'));});
test('default search excludes expansion entries unless explicitly included',()=>{const x=setup(),row={id:'expansion',title:'Viper expansion',titleKey:'viper expansion',searchKey:'viper expansion',type:'reference',region:'Toussaint',expansion:'baw',href:'#future'};const context={tasks:x.tasks,state:x.state,engine:x.engine};assert.equal(x.model.search([row],'Viper',{},context).length,0);assert.equal(x.model.search([row],'Viper',{expansions:true},context).length,1);});
test('searching and reading history do not mutate game progress or canonical tasks',()=>{const x=setup(),before=JSON.stringify({tasks:x.tasks,state:x.state});x.find('skull');x.find('Missing');x.model.readHistory('{bad',x.index);assert.equal(JSON.stringify({tasks:x.tasks,state:x.state}),before);});
test('recent history is bounded, deduplicated and rejects obsolete entries',()=>{const x=setup();let h=x.model.readHistory(JSON.stringify({queries:['Skull','Skull',null,''],entries:['poi-4','poi-4','obsolete']}),x.index);assert.deepEqual(Array.from(h.queries),['Skull']);assert.deepEqual(Array.from(h.entries),['poi-4']);for(let i=0;i<12;i++)h=x.model.remember(h,{query:'Query '+i,id:'poi-4'});assert.equal(h.queries.length,8);assert.equal(h.queries[0],'Query 11');assert.equal(h.entries.length,1);h=x.model.remember(h,{query:'QUERY 11'});assert.equal(h.queries.length,8);assert.equal(h.queries[0],'QUERY 11');});
test('malformed saved history degrades to empty history',()=>{const x=setup();for(const raw of ['{bad','null','17','{"queries":{},"entries":42}']){const h=x.model.readHistory(raw,x.index);assert.equal(h.queries.length,0);assert.equal(h.entries.length,0);}});
